import React, { useState, useEffect, useRef } from "react";
import { Link } from "react-router-dom";
import "./Navbar.css";

const Navbar = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false); // Estado para detectar el scroll
  const menuRef = useRef(null);
  const menuIconRef = useRef(null);

  const toggleMenu = () => setIsOpen(!isOpen);
  const closeMenu = () => setIsOpen(false);

  // Detectar clic fuera del menú para cerrarlo
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (
        menuRef.current && !menuRef.current.contains(event.target) &&
        menuIconRef.current && !menuIconRef.current.contains(event.target)
      ) {
        closeMenu();
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Detectar si se hizo scroll para activar la navbar fija
  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > window.innerHeight * 0.8) {
        setIsScrolled(true);
      } else {
        setIsScrolled(false);
      }
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <>
      {/* Línea gris debajo del Home */}
      <div className="separador"></div>

      <nav className={`navbar ${isScrolled ? "navbar-fixed" : ""}`}>
        <div className="navbar-container">
          <h1 className="logo">
            <Link to="/"><span className="trader">FREE</span> TRADER</Link>
          </h1>

          {/* Menú hamburguesa */}
          <div
            ref={menuIconRef}
            className={`menu-icon ${isOpen ? "open" : ""}`}
            onClick={toggleMenu}
          >
            <i className={`fa-solid ${isOpen ? "fa-xmark" : "fa-bars"}`} aria-hidden="true"></i>
          </div>

          {/* Enlaces */}
          <ul ref={menuRef} className={`nav-links ${isOpen ? "active" : ""}`}>
            <li><Link to="/" onClick={closeMenu}>Inicio</Link></li>
            <li><Link to="/cursos" onClick={closeMenu}>Cursos</Link></li>
            <li><Link to="/sobre-nosotros" onClick={closeMenu}>Sobre Nosotros</Link></li>
          </ul>
        </div>
      </nav>
    </>
  );
};

export default Navbar;
